from fractions import Fraction
import math

def ln_series(x, terms):
    return sum(Fraction((-1)**n, n + 1) * x**(n + 1) for n in range(terms))

def arctan_series(x, terms):
    return sum(Fraction((-1)**n, 2*n + 1) * x**(2*n + 1) for n in range(terms))

for x, terms in [(Fraction(1, 2), 10), (Fraction(1, 10), 5), (Fraction(1), 10), (Fraction(1), 1000)]:
    s = ln_series(x, terms)
    print(f"ln(1 + {x}) with {terms} terms: {float(s):.10f}, true {math.log(1 + x):.10f}, error {float(s) - math.log(1 + x):.1e}")
for x, terms in [(Fraction(1, 2), 10), (Fraction(1), 10), (Fraction(1), 1000)]:
    s = arctan_series(x, terms)
    print(f"arctan({x}) with {terms} terms: {float(s):.10f}, true {math.atan(x):.10f}, error {float(s) - math.atan(x):.1e}")
machin = 16 * arctan_series(Fraction(1, 5), 5) - 4 * arctan_series(Fraction(1, 239), 2)
print(f"Machin's formula, 5 and 2 terms: pi = {float(machin):.10f}, true {math.pi:.10f}")
x = Fraction(5, 6)
print(f"sum k (5/6)^(k-1) / 6, from 1/(1 - x)^2: {Fraction(1, 6) / (1 - x)**2}")
